1: user www-data;
2: worker_processes auto;
3: pid /run/nginx.pid;
4: include /etc/nginx/modules-enabled/*.conf;
5: 
6: events {
7:     worker_connections 768;
8:     # multi_accept on;
9: }
10: 
11: http {
12:     ##
13:     # Basic Settings
14:     ##
15: 
16:     sendfile on;
17:     tcp_nopush on;
18:     tcp_nodelay on;
19:     keepalive_timeout 65;
20:     types_hash_max_size 2048;
21: 
22:     # server_names_hash_bucket_size 64;
23:     # server_name_in_redirect off;
24: 
25:     include /etc/nginx/mime.types;
26:     default_type application/octet-stream;
27: 
28:     ##
29:     # Logging Settings
30:     ##
31: 
32:     access_log /var/log/nginx/access.log;
33:     error_log /var/log/nginx/error.log;
34: 
35:     ##
36:     # Gzip Settings
37:     ##
38: 
39:     gzip on;
40: 
41:     # gzip_vary on;
42:     # gzip_proxied any;
43:     # gzip_comp_level 6;
44:     # gzip_buffers 16 8k;
45:     # gzip_http_version 1.1;
46:     # gzip_types text/plain text/css application/json application/javascript text/xml application/xml application/xml+rss text/javascript;
47: 
48:     ##
49:     # Virtual Host Configs
50:     ##
51: 
52:     include /etc/nginx/conf.d/*.conf;
53:     include /etc/nginx/sites-enabled/*;
54: }

1: server {
2:     listen 80;
3:     server_name {{ server_name }};
4: 
5:     # Redirect all HTTP to HTTPS
6:     {% if ssl_enabled %}
7:     return 301 https://$server_name$request_uri;
8: }
9: 
10: server {
11:     listen 443 ssl http2;
12:     server_name {{ server_name }};
13: 
14:     root {{ document_root }};
15:     index index.html index.htm index.php;
16: 
17:     # SSL Configuration
18:     ssl_certificate {{ cert_file }};
19:     ssl_certificate_key {{ key_file }};
20: 
21:     # SSL Security
22:     ssl_protocols TLSv1.2 TLSv1.3;
23:     ssl_ciphers ECDHE-RSA-AES256-GCM-SHA512:DHE-RSA-AES256-GCM-SHA512:ECDHE-RSA-AES256-GCM-SHA384:DHE-RSA-AES256-GCM-SHA384:ECDHE-RSA-AES256-SHA384;
24:     ssl_prefer_server_ciphers on;
25:     ssl_session_cache shared:SSL:10m;
26:     ssl_session_timeout 10m;
27: 
28:     # HSTS
29:     add_header Strict-Transport-Security "max-age=31536000; includeSubDomains" always;
30:     {% else %}
31:     root {{ document_root }};
32:     index index.html index.htm index.php;
33:     {% endif %}
34: 
35:     # Security Headers
36:     add_header X-Frame-Options DENY always;
37:     add_header X-Content-Type-Options nosniff always;
38:     add_header X-XSS-Protection "1; mode=block" always;
39:     add_header Referrer-Policy "strict-origin-when-cross-origin" always;
40:     add_header Content-Security-Policy "default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; font-src 'self';" always;
41: 
42:     # Gzip compression
43:     gzip on;
44:     gzip_vary on;
45:     gzip_min_length 1024;
46:     gzip_types text/plain text/css text/xml text/javascript application/javascript application/xml+rss application/json;
47: 
48:     location / {
49:         try_files $uri $uri/ =404;
50:     }
51: 
52:     # Hide .htaccess files
53:     location ~ /\.ht {
54:         deny all;
55:     }
56: 
57:     # Hide sensitive files
58:     location ~ /\.(git|svn) {
59:         deny all;
60:     }
61: 
62:     access_log /var/log/nginx/{{ server_name }}_access.log;
63:     error_log /var/log/nginx/{{ server_name }}_error.log;
64: }

1: # Hide nginx version
2: server_tokens off;
3: 
4: # Rate limiting
5: limit_req_zone $binary_remote_addr zone=login:10m rate=10r/m;
6: limit_req_zone $binary_remote_addr zone=api:10m rate=30r/m;
7: 
8: # Prevent buffer overflow attacks
9: client_body_buffer_size 1K;
10: client_header_buffer_size 1k;
11: client_max_body_size 1k;
12: large_client_header_buffers 2 1k;
13: 
14: # Timeout settings
15: client_body_timeout 10;
16: client_header_timeout 10;
17: send_timeout 10;
18: 
19: # SSL settings
20: ssl_session_cache shared:SSL:10m;
21: ssl_session_timeout 10m;
22: ssl_protocols TLSv1.2 TLSv1.3;
23: ssl_ciphers ECDHE-RSA-AES256-GCM-SHA512:DHE-RSA-AES256-GCM-SHA512:ECDHE-RSA-AES256-GCM-SHA384:DHE-RSA-AES256-GCM-SHA384:ECDHE-RSA-AES256-SHA384;
24: ssl_prefer_server_ciphers on;
